#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms_swapped(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms_swapped(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms_swapped(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms_swapped(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn push_digit(out: &mut String, d: u32) -> () {
    let digit_code: u32 = if d < 10 {
        48 + d % 16
    } else {
        87 + d % 16
    };
    match char::from_u32(digit_code) {
        None => {},
        Some(c) => out.push(c),
    }
}

#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms_swapped(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms_swapped(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms_swapped(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn plan(cx: &Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize) -> Plan {
    let num: String = encode_terms::dec(k as u64);
    let title: String = types::cat5(num.as_str(), ": ", o.code.as_str(), " ", o.msg.as_str());
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..o.assumptions.len()
        invariant 0 <= i && i <= o.assumptions.len(),
    {
        asserted.push(types::cat3("(assert ", o.assumptions[i].as_str(), ")"));
    }
    let q0: String = types::cat4(encode_terms::join(asserted.as_slice(), "\n").as_str(), "\n(assert (not ", o.goal.as_str(), "))");
    let q1: String = valid_instances(cx.valid.as_slice(), q0);
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    let probe: Option<String> = probe_base(cx, q.as_str(), relevant.as_str(), Forms::Probe);
    let abstracted: Option<Abstracted> = if has(q.as_str(), "(bv2nat ") {
        abstracted_of(cx, pg, base.as_str(), q.as_str())
    } else {
        None
    };
    let probe_script: String = match &probe {
        None => String::new(),
        Some(pb) => { let mut ps: String = types::cat3("; probe of obligation ", title.as_str(), "\n(reset)\n"); ps.push_str(types::cat5(pb.as_str(), "\n", cx.limit.as_str(), "\n", q.as_str()).as_str()); ps.push_str("\n(check-sat)\n"); ps },
    };
    let mut script: String = String::new();
    match &abstracted {
        None => { script.push_str(probe_script.as_str()); script.push_str(types::cat3("; obligation ", title.as_str(), "\n(reset)\n").as_str()); },
        Some(ab) => { script.push_str(types::cat3("; obligation ", title.as_str(), " (bit operations abstracted)\n(reset)\n").as_str()); script.push_str(types::cat4(ab.head.as_str(), "\n", ab.query.as_str(), "\n(check-sat)\n").as_str()); script.push_str(probe_script.as_str()); script.push_str(types::cat3("; exact query of obligation ", num.as_str(), "\n(reset)\n").as_str()); },
    }
    script.push_str(types::cat4(base.as_str(), "\n", q.as_str(), "\n(check-sat)\n").as_str());
    Plan { q: q, relevant: relevant, base: base, probe: probe, abstracted: abstracted, script: script }
}

#[effects(alloc)]
fn reach_points(cx: &Ctx, pg: &encode_spec::Prog, points: &[encode_exec::Reach], enc: &mut encode_spec::Enc) -> String {
    let mut script: String = String::new();
    for k in 0..points.len()
        invariant 0 <= k && k <= points.len(),
    {
        let mut title: String = types::cat5(" of reach point ", encode_terms::dec(k as u64).as_str(), ": ", points[k].what.as_str(), " ");
        title.push_str(types::cat4(encode_terms::dec(points[k].span.lo as u64).as_str(), " ", encode_terms::dec(points[k].span.hi as u64).as_str(), "\n(reset)\n").as_str());
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..points[k].pc.len()
            invariant 0 <= i && i <= points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", points[k].pc[i].as_str(), ")"));
        }
        let q1: String = valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = relevant_axioms(q.as_str(), cx.axioms.as_slice());
        let used: String = needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
        let tail: String = types::cat5("\n", cx.limit.as_str(), "\n", q.as_str(), "\n(check-sat)\n");
        match probe_base(cx, q.as_str(), relevant.as_str(), Forms::SatProbe) {
            None => {},
            Some(pb) => { script.push_str(types::cat4("; probe", title.as_str(), pb.as_str(), tail.as_str()).as_str()); },
        }
        match bv_reach(cx.decls.as_str(), q.as_str(), enc, pg) {
            None => {},
            Some(bq) => { if bq.exact { script.push_str("; exact bit-vector form"); } else { script.push_str("; bit-vector form"); } script.push_str(title.as_str()); script.push_str(types::cat5(cx.header.as_str(), "\n", bq.script.as_str(), "\n", cx.limit.as_str()).as_str()); script.push_str("\n(check-sat)\n"); },
        }
        match rec_base(cx, q.as_str()) {
            None => {},
            Some(rb) => { script.push_str(types::cat4("; recursive form", title.as_str(), rb.as_str(), tail.as_str()).as_str()); },
        }
        script.push_str(types::cat4("; full query", title.as_str(), base.as_str(), "\n(set-option :rlimit 1000000)\n").as_str());
        script.push_str(types::cat2(q.as_str(), "\n(check-sat)\n").as_str());
    }
    script
}

#[effects(alloc)]
fn relevant_axioms(text: &str, axioms: &[encode_terms::Pair]) -> String {
    axioms_in_forms(axioms, text, Forms::Full)
}

#[effects(alloc, io, nondet)]
#[uses(unsat_only)]
fn decide(sol: &mut solver::Solver, cx: &encode_query::Ctx, pg: &encode_spec::Prog, o: &encode_spec::Obl, k: usize, pl: &encode_query::Plan, inputs: &[encode_spec::Shown], path: &str, unit: &str, names: &table::Table<String>, opts: &Opts, t: &mut Tally, diags: &mut diag::Diags) -> Verdict {
    let mut v: Verdict = Verdict { proved: false, by: 9, ob_max: 0, stages: 0, broken: false };
    let num: String = encode_terms::dec(k as u64);
    let mut answer: Option<Ans> = None;
    let mut answered: String = types::cat3(pl.base.as_str(), "\n", pl.q.as_str());
    match &pl.abstracted {
        None => {},
        Some(ab) => { let mut ps: Vec<String> = Vec::new(); ps.push(ab.head.clone()); ps.push(ab.query.clone()); let a: Ans = asked(sol, ps.as_slice()); add(t, &mut v, spent(sol, &a), true); if a.kind == 0 { answer = Some(a.clone()); } },
    }
    let mut retry: Option<encode_query::Retry> = None;
    let mut retried: bool = false;
    if is_open(&answer) {
        match &pl.probe {
            None => {},
            Some(pb) => { let mut ps1: Vec<String> = Vec::new(); ps1.push(pb.clone()); ps1.push(cx.limit.clone()); ps1.push(pl.q.clone()); let a1: Ans = asked(sol, ps1.as_slice()); add(t, &mut v, spent(sol, &a1), true); if a1.kind == 0 || a1.kind == 1 { answered = types::cat3(pb.as_str(), "\n", pl.q.as_str()); answer = Some(a1.clone()); } if is_open(&answer) && cx.parts.len() > 0 { retry = encode_query::retry_script(cx, pg, pl.q.as_str()); retried = true; match &retry { None => {}, Some(r) => { v.stages = v.stages | cache::early_retry(); t.script.push_str(early_retry_text(num.as_str(), r.head.as_str(), cx.limit.as_str(), r.inst.as_str(), pl.q.as_str()).as_str()); let mut ps2: Vec<String> = Vec::new(); ps2.push(r.head.clone()); ps2.push(cx.limit.clone()); ps2.push(types::cat2(r.inst.as_str(), pl.q.as_str())); let a2: Ans = asked(sol, ps2.as_slice()); add(t, &mut v, spent(sol, &a2), false); if a2.kind == 0 { answer = Some(a2.clone()); } else if a2.kind == 1 && r.complete { answered = types::cat4(r.head.as_str(), "\n", r.inst.as_str(), pl.q.as_str()); answer = Some(a2.clone()); } }, } } },
        }
    }
    let mut last: Ans = match answer {
        None => { let mut ps3: Vec<String> = Vec::new(); ps3.push(pl.base.clone()); ps3.push(pl.q.clone()); let a3: Ans = asked(sol, ps3.as_slice()); add(t, &mut v, spent(sol, &a3), true); a3 },
        Some(got) => got,
    };
    if undecided(&last, opts.who) && cx.parts.len() > 0 {
        if !retried {
            retry = encode_query::retry_script(cx, pg, pl.q.as_str());
        }
        match &retry {
            None => {},
            Some(r2) => { t.script.push_str(types::cat3("; retry of obligation ", num.as_str(), " with ground instances\n(reset)\n").as_str()); t.script.push_str(types::cat5(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str(), "\n(check-sat)\n").as_str()); let mut ps4: Vec<String> = Vec::new(); ps4.push(r2.head.clone()); ps4.push(types::cat2(r2.inst.as_str(), pl.q.as_str())); let a4: Ans = asked(sol, ps4.as_slice()); add(t, &mut v, spent(sol, &a4), false); if a4.kind == 0 { last = a4; v.stages = v.stages | cache::late_retry(); } else if a4.kind == 1 && r2.complete { last = a4; answered = types::cat4(r2.head.as_str(), "\n", r2.inst.as_str(), pl.q.as_str()); } else if a4.kind == 1 && last.kind != 3 { last = Ans { kind: 2, text: String::from("a model exists for the instantiated definitions only") }; } },
        }
    }
    let shown: Vec<encode_spec::Shown> = shown_inputs(inputs, o);
    let mut bounded_none: bool = false;
    let mut bounded_found: bool = false;
    if undecided(&last, opts.who) && opts.bounded {
        let bounds: String = model::input_bounds(shown.as_slice());
        if bounds.len() > 0 {
            let share: u64 = if opts.rlimit / 10 >= 1 {
                opts.rlimit / 10
            } else {
                1
            };
            let blimit: String = types::cat3("(set-option :rlimit ", encode_terms::dec(share).as_str(), ")");
            t.script.push_str(types::cat3("; bounded search of obligation ", num.as_str(), "\n(reset)\n").as_str());
            t.script.push_str(types::cat5(pl.base.as_str(), "\n", blimit.as_str(), "\n", pl.q.as_str()).as_str());
            t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
            let mut ps5: Vec<String> = Vec::new();
            ps5.push(pl.base.clone());
            ps5.push(blimit.clone());
            ps5.push(types::cat3(pl.q.as_str(), "\n", bounds.as_str()));
            let a5: Ans = asked(sol, ps5.as_slice());
            add(t, &mut v, spent(sol, &a5), false);
            if a5.kind == 1 {
                last = a5;
                answered = types::cat5(pl.base.as_str(), "\n", pl.q.as_str(), "\n", bounds.as_str());
                bounded_found = true;
            } else if a5.kind == 0 {
                let dom: String = domain(cx, pg, o);
                let dom_rel: String = encode_query::relevant_axioms(dom.as_str(), cx.axioms.as_slice());
                let dom_base: String = match encode_query::probe_base(cx, dom.as_str(), dom_rel.as_str(), encode_query::Forms::SatProbe) {
                    None => { let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(dom_rel.as_str(), cx.decls.as_str(), "\n", dom.as_str()).as_str()); types::cat4(cx.prefix.as_str(), used.as_str(), dom_rel.as_str(), cx.decls.as_str()) },
                    Some(b) => b,
                };
                t.script.push_str(types::cat3("; bounded domain of obligation ", num.as_str(), "\n(reset)\n").as_str());
                t.script.push_str(types::cat5(dom_base.as_str(), "\n", blimit.as_str(), "\n", dom.as_str()).as_str());
                t.script.push_str(types::cat3("\n", bounds.as_str(), "(check-sat)\n").as_str());
                let mut ps6: Vec<String> = Vec::new();
                ps6.push(dom_base.clone());
                ps6.push(blimit.clone());
                ps6.push(types::cat3(dom.as_str(), "\n", bounds.as_str()));
                let a6: Ans = asked(sol, ps6.as_slice());
                add(t, &mut v, spent(sol, &a6), false);
                bounded_none = a6.kind == 1;
            }
        }
    }
    if last.kind == 0 {
        v.by = last.kind;
        v.proved = true;
        return v;
    }
    let mut msg: String = types::cat4(o.msg.as_str(), " in `", path, "`");
    if last.kind == 1 {
        let confirmed: Result<(), String> = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u) => Ok(()),
            Err(why) => { let exact: String = model::f64_interpreted(answered.as_str()); let mut ps7: Vec<String> = Vec::new(); ps7.push(exact.clone()); let a7: Ans = asked(sol, ps7.as_slice()); if a7.kind == 1 { model::f64_model_check(sol, exact.as_str()) } else if a7.kind == 0 { Err(String::from("it holds with IEEE 754 arithmetic, which only `by (bit_vector)` uses")) } else { Err(why) } },
        };
        match confirmed {
            Ok(u1) => { let cex: String = model::counterexample(sol, shown.as_slice(), &pg.pr.t, names); let hidden: Vec<encode_terms::Pair> = hidden_pairs(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); if cex.len() > 0 && hidden.len() > 0 && opts.jobs.len() == 0 { let mut ticked: Vec<String> = Vec::new(); for h in 0..hidden.len() invariant 0 <= h && h <= hidden.len(), { ticked.push(types::cat3("`", hidden[h].a.as_str(), "`")); } msg.push_str(types::cat3("; counterexample with ", encode_terms::join(ticked.as_slice(), ", ").as_str(), " unknown: ").as_str()); msg.push_str(cex.as_str()); let inst: String = match encode_query::retry_script(cx, pg, pl.q.as_str()) { None => String::new(), Some(r9) => r9.inst.clone(), }; let assumed: Vec<String> = model::assumed(sol, answered.as_str(), inst.as_str(), hidden.as_slice(), shown.as_slice()); if assumed.len() > 0 { msg.push_str(", assuming "); msg.push_str(encode_terms::join(assumed.as_slice(), ", ").as_str()); } } else if cex.len() > 0 { msg.push_str("; counterexample: "); msg.push_str(cex.as_str()); } if bounded_found { msg.push_str(" (found by the search within |integers| <= 8, lengths <= 4, after the solver could not decide)"); } let hint: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit); let d: diag::Diag = with_hint(diag::new(o.code.as_str(), o.span, msg.as_str()), hint.as_slice(), false); let plain: bool = no_fix(&d); if plain && o.code == "E0820" { diags.push(diag::fix(d, "check `s.is_char_boundary(a) && s.is_char_boundary(b) && a <= b` before `&s[a..b]`, or require it", None)); } else if plain && cex.len() == 0 { diags.push(diag::fix(d, model::no_inputs_help(o.code.as_str()).as_str(), None)); } else { diags.push(d); } },
            Err(why2) => diags.push(f64_undecided(o, path, why2.as_str())),
        }
        return v;
    }
    if last.kind == 2 {
        msg.push_str(types::cat3(": solver could not decide (", solver::unknown_reason(last.text.as_str(), opts.who).as_str(), ")").as_str());
        let cex2: String = match model::f64_model_check(sol, answered.as_str()) {
            Ok(u2) => model::counterexample(sol, shown.as_slice(), &pg.pr.t, names),
            Err(why3) => String::new(),
        };
        if cex2.len() > 0 {
            msg.push_str("; unconfirmed counterexample: ");
            msg.push_str(cex2.as_str());
        }
        let bound: Option<diag::Bound> = if bounded_none {
            Some(diag::Bound { b: 8, l: 4 })
        } else {
            None
        };
        let d2: diag::Diag = diag::Diag { code: String::from("E0811"), span: o.span, message: msg, fix: None, obligation: Some(o.code.clone()), bounded: bound };
        let hint2: Vec<String> = hidden_predicates(pg, cx.axioms.as_slice(), types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str(), unit);
        diags.push(with_hint(d2, hint2.as_slice(), has_nonlinear_product(types::cat2(pl.q.as_str(), pl.relevant.as_str()).as_str())));
        return v;
    }
    match limit_of(&last, opts.who) {
        None => { diags.push(diag::new("E0812", o.span, types::cat2("solver error: ", last.text.as_str()).as_str())); v.broken = true; },
        Some(why4) => { msg.push_str(types::cat3(": solver could not decide (", why4.as_str(), ")").as_str()); let bound2: Option<diag::Bound> = if bounded_none { Some(diag::Bound { b: 8, l: 4 }) } else { None }; diags.push(diag::Diag { code: String::from("E0811"), span: o.span, message: msg.clone(), fix: None, obligation: Some(o.code.clone()), bounded: bound2 }); },
    }
    v
}

#[effects(alloc, io, nondet)]
fn reach_points(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, r: &encode_query::Reaching, pg: &encode_spec::Prog, path: &str, unit: &str, rows: &mut Vec<Point>) -> usize {
    let mut undecided: usize = 0;
    for k in 0..r.points.len()
        invariant 0 <= k && k <= r.points.len(),
    {
        let mut asserted: Vec<String> = Vec::new();
        for i in 0..r.points[k].pc.len()
            invariant 0 <= i && i <= r.points[k].pc.len(),
        {
            asserted.push(types::cat3("(assert ", r.points[k].pc[i].as_str(), ")"));
        }
        let q1: String = encode_query::valid_instances(r.cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
        let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
        let relevant: String = encode_query::relevant_axioms(q.as_str(), r.cx.axioms.as_slice());
        let used: String = encode_query::needed_decls(r.cx.sds.as_slice(), r.cx.dts.as_slice(), types::cat4(relevant.as_str(), r.cx.decls.as_str(), "\n", q.as_str()).as_str());
        let base: String = types::cat4(r.cx.prefix.as_str(), used.as_str(), relevant.as_str(), r.cx.decls.as_str());
        if !prove::reusable(&st.slot) {
            prove::let_go(&mut st.slot);
        }
        if prove::idle(&st.slot) {
            match solver::start(who, z3) {
                Ok(s) => { st.slot = Some(s); },
                Err(e) => {},
            }
        }
        if prove::idle(&st.slot) {
            undecided = undecided.saturating_add(r.points.len() - k);
            break;
        }
        match std::mem::replace(&mut st.slot, None) {
            None => {},
            Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = reach_with(&mut sol, st, who, &r.cx, pg, q.as_str(), relevant.as_str(), base.as_str(), path, unit); if a.kind == 0 { rows.push(Point { path: String::from(path), span: r.points[k].span, what: r.points[k].what.clone() }); st.slot = Some(sol); } else if a.kind == 1 { st.slot = Some(sol); } else if a.kind == 2 { undecided = undecided.saturating_add(1); st.slot = Some(sol); } else { undecided = undecided.saturating_add(1); match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } } },
        }
    }
    undecided
}

#[effects(alloc, io, nondet)]
fn sat_of(st: &mut Solving, z3: &mut toolchain::Z3, who: solver::Asker, cx: &encode_query::Ctx, pg: &encode_spec::Prog, pc: &[String]) -> u8 {
    let mut asserted: Vec<String> = Vec::new();
    for i in 0..pc.len()
        invariant 0 <= i && i <= pc.len(),
    {
        asserted.push(types::cat3("(assert ", pc[i].as_str(), ")"));
    }
    let q1: String = encode_query::valid_instances(cx.valid.as_slice(), encode_terms::join(asserted.as_slice(), "\n"));
    let q: String = types::cat3(q1.as_str(), "\n", encode_spec::struct_facts(pg, q1.as_str()).as_str());
    let relevant: String = encode_query::relevant_axioms(q.as_str(), cx.axioms.as_slice());
    let used: String = encode_query::needed_decls(cx.sds.as_slice(), cx.dts.as_slice(), types::cat4(relevant.as_str(), cx.decls.as_str(), "\n", q.as_str()).as_str());
    let full: String = types::cat4(cx.prefix.as_str(), used.as_str(), relevant.as_str(), cx.decls.as_str());
    if !prove::reusable(&st.slot) {
        prove::let_go(&mut st.slot);
    }
    if prove::idle(&st.slot) {
        match solver::start(who, z3) {
            Ok(s) => { st.slot = Some(s); },
            Err(e) => { st.down = true; return 2; },
        }
    }
    match std::mem::replace(&mut st.slot, None) {
        None => 2,
        Some(held) => { let mut sol: solver::Solver = held; let a: prove::Ans = sat_with(&mut sol, st, who, cx, pg, q.as_str(), relevant.as_str(), full.as_str()); if a.kind == 0 { st.slot = Some(sol); return 0; } if a.kind == 1 { st.slot = Some(sol); return 1; } if a.kind == 2 { st.slot = Some(sol); return 2; } match prove::limit_of(&a, who) { None => { let status: Option<i32> = solver::close(&mut sol); }, Some(why) => { st.slot = Some(sol); }, } 2 },
    }
}

#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}
